inline std::vector<double> dl_opening_scores(const DLInputs& I)
{
	std::vector<double> out(I.gf.size(), -1e300);
	double c[64];
	dl_detail::mlp2_const<41, GF_N, 8>(I.z, DL_OPEN_MEAN, DL_OPEN_STD, DL_OPEN_W, c);
	for (std::size_t g = 0; g < I.gf.size(); ++g)
		if (I.reached[g])
			out[g] = dl_detail::mlp2_split<41, GF_N, 8>(I.gf[g].data(), c, DL_OPEN_MEAN, DL_OPEN_STD, DL_OPEN_W, DL_OPEN_B);
	return out;
}

