// prev: the group the body captured last; champion_type: cambc::champion_type order; round: the game round; only: score these
// groups only (the others -1e300): about 1,600 fuel a group, so a game turn scores a candidate list, not all 64 groups
inline std::vector<double> dl_next_scores(const Compact& C, const DLInputs& I, int prev, int champion_type, int round,
										  const std::vector<int>* only = nullptr)
{
	std::vector<double> out(I.gf.size(), -1e300);
	if (prev < 0 || prev >= static_cast<int>(I.gf.size()))
		return out;
	double xc[14 + MW_NF], c[64], x[GF_N + 1];
	xc[0] = round / 2000.0;
	for (int k = 0; k < 13; ++k)
		xc[1 + k] = k == champion_type ? 1.0 : 0.0;
	for (int i = 0; i < MW_NF; ++i)
		xc[14 + i] = I.z[i];
	dl_detail::mlp2_const<56, GF_N + 1, 8>(xc, DL_NEXT_MEAN, DL_NEXT_STD, DL_NEXT_W, c);
	const std::size_t n = only ? only->size() : I.gf.size();
	for (std::size_t k = 0; k < n; ++k)
	{
		const auto g = only ? static_cast<std::size_t>((*only)[k]) : k;
		if (g >= I.gf.size() || !I.reached[g])
			continue;
		for (int i = 0; i < GF_N; ++i)
			x[i] = I.gf[g][static_cast<std::size_t>(i)];
		x[GF_N] = detail::box_dist(C.bx[static_cast<std::size_t>(prev)], C.bx[g]) / 100.0;
		out[g] = dl_detail::mlp2_split<56, GF_N + 1, 8>(x, c, DL_NEXT_MEAN, DL_NEXT_STD, DL_NEXT_W, DL_NEXT_B);
	}
	return out;
}

